-- How often every pair of countries voted the same way at the UN General Assembly -- 1.8M pairs.
-- Auto-generated by scripts/gen_evidence_pages.py: 1,823,352 rows > 100k, so this is a BOUNDED pre-aggregate (parquet-safe by construction), not select *.
-- grouped on year-like text/number column YEAR (NOT date-cast -- avoids the 8-digit epoch trap); LIMIT bounds it.
select "YEAR" as year, count(*) as records
from THE_LIBRARY.GOVERNMENT.UN_VOTE_AGREEMENT_PAIRS
group by 1
order by 1
limit 1000
